const defaultState=structuredClone(SEED_DATA);
let state=loadState();
let currentPage='dashboard';

function clone(x){return structuredClone(x)}
function uniqById(arr){const seen=new Set();return (arr||[]).filter(x=>x&&x.id&&!seen.has(x.id)&&seen.add(x.id))}
function loadState(){try{return JSON.parse(localStorage.getItem('businessEcoState'))||clone(defaultState)}catch{return clone(defaultState)}}
function save(){localStorage.setItem('businessEcoState',JSON.stringify(state))}
function byName(arr,name){return (arr||[]).find(x=>x.name===name)}
function ensureOffer(o){state.offers=state.offers||[];if(!state.offers.some(x=>x.id===o.id||x.name===o.name))state.offers.push(clone(o))}
function ensurePackage(p){state.packages=state.packages||[];if(!state.packages.some(x=>x.id===p.id||x.name===p.name))state.packages.push(clone(p))}
function removeCandidates(names){const s=new Set(names);state.candidates=(state.candidates||[]).filter(c=>!s.has(c.name))}

function migrateState(){
  state.businesses=state.businesses||[];state.connections=state.connections||[];state.candidates=state.candidates||[];
  state.brainstorm=state.brainstorm||[];state.inspiration=state.inspiration||[];state.offers=state.offers||[];state.packages=state.packages||[];
  if((state.dataSchemaVersion||1)<5){
    const deko=state.businesses.find(b=>b.id==='eventdeko'||b.name==='Eventdeko-Verleih');
    if(deko){deko.name='Eventdeko & Eventausstattung-Verleih';deko.description='Verleih von Eventdeko und Ausstattung: Deko, Teller, Gläser, Tischwäsche sowie ergänzend Eventmöbel wie Loungemöbel, Stehtische, mobile Bars, Bögen und Staffeleien.'}
    const pancake=state.businesses.find(b=>b.id==='pancake'||b.name==='Pancake Boxes / Store');
    if(pancake){pancake.name='Pancake & Waffle Boxes / Store';pancake.description='Pancakes und Waffeln mit Toppings, Früchten, Saucen und Dips als Box, To-go- oder Store-Konzept.'}
    SEED_DATA.offers.forEach(ensureOffer);SEED_DATA.packages.forEach(ensurePackage);
    removeCandidates(['Event Furniture Rental','Signature Lemonade / Fruit Drinks','Fruit Cups / Chocolate Fruit Cups','Waffle-on-a-stick / Mini-Waffle Bar','Proposal Planning','JGA Planning / Bachelorette Packages','Micro-Weddings / Elopement Packages','Corporate Event Packages','Welcome Boxes für Airbnb','Romantic Setup im Airbnb','Farm Stay Packages','Kindergeburtstage auf dem Hof','Tierpatenschafts-Geschenkboxen','Tier-/Hof-Merchandise','Self-Service Farm Shop','Christmas Farm / Weihnachtsmarkt auf dem Hof','Custom Wedding Favours / Gastgeschenke','Digital Wedding Templates','Pumpkin Patch / saisonale Erlebnisfläche','Pick-your-own Flowers / Blumenfeld','Workshops']);
    const bar=byName(state.candidates,'Mobile Bar / Mocktail Bar');if(bar){bar.name='Mobile Getränke- & Mocktail Bar';bar.description='Mobile Bar für alkoholfreie Cocktails, Signature-Limonaden, Eistees und Fruchtgetränke mit echter Frucht und passendem Eventdesign.';bar.synergies=['Eis mit echten Früchten','Eventplanning','Hochzeitslocation','Eventdeko & Eventausstattung-Verleih','Hofladen'];bar.resources='Mobiler Tresen, Kühlung, Gläser/Becher, Eis, Getränkezubereitung';bar.channels='Events, Pop-ups, Hof'}
    const flower=byName(state.candidates,'Flower Bar / Build-your-own-Bouquet');if(flower){flower.target='Hochzeiten, JGAs, Hofbesucher und Eventgäste';flower.channels='Events, Hofladen, Pop-ups'}
    const retreat=byName(state.candidates,'Creative Retreats');if(retreat){retreat.description='Mehrtagige Kreativaufenthalte mit Übernachtung, kreativen Aktivitäten, Food und optional Tieren/Natur.';retreat.synergies=['Airbnb','Gnadenhof','Journals & Planer','DIY-Eventstationen','Food & Desserts'];retreat.resources='Unterkunft, Kreativraum, Material und Programmplanung'}
    const tiny=byName(state.candidates,'Tiny Event Spaces');if(tiny)tiny.synergies=['Hochzeitslocation','DIY-Eventstationen','Eventdeko & Eventausstattung-Verleih','Gnadenhof'];
    state.dataSchemaVersion=DATA_SCHEMA_VERSION;
  }
  state.businesses=uniqById(state.businesses);state.connections=uniqById(state.connections);state.candidates=uniqById(state.candidates);state.offers=uniqById(state.offers);state.packages=uniqById(state.packages);
  save();
}
migrateState();

document.addEventListener('DOMContentLoaded',()=>{const v=document.getElementById('appVersion');if(v)v.textContent=APP_VERSION;});
const pages=[['dashboard','Dashboard'],['businesses','Businesses'],['offers','Angebote & Produkte'],['packages','Pakete'],['mindmap','Master Mindmap'],['synergies','Synergien'],['candidates','Kandidaten'],['inspiration','Inspiration'],['brainstorm','Brainstorming'],['implementation','Umsetzung'],['backup','Backup']];
const nav=document.getElementById('nav');
pages.forEach(([id,label])=>{const b=document.createElement('button');b.className='nav-btn';b.textContent=label;b.onclick=()=>renderPage(id);b.dataset.page=id;nav.appendChild(b)});
function renderPage(id){
  currentPage=id;document.querySelectorAll('.nav-btn').forEach(b=>b.classList.toggle('active',b.dataset.page===id));
  const titles={dashboard:['Dashboard','Dein gesamtes Business-Netzwerk auf einen Blick.'],businesses:['Businesses','Bestätigte eigenständige Businesses und Steckbriefe.'],offers:['Angebote & Produkte','Produkte, Add-ons, Events und Vertriebsformen innerhalb deiner Businesses.'],packages:['Pakete','Cross-Business-Pakete, die mehrere Businesses zu einem Angebot verbinden.'],mindmap:['Master Mindmap','Interaktive Karte aller bestätigten Businesses und Verbindungen.'],synergies:['Synergien','Cross-Selling, Kundenfluss und gemeinsame Ressourcen.'],candidates:['Kandidaten','Nur Ideen, die noch nicht bestätigt oder einsortiert wurden.'],inspiration:['Inspiration','Bilder und Moodboard-Ideen mit Freigabestatus.'],brainstorm:['Brainstorming','Lose Gedanken, bevor daraus Kandidaten werden.'],implementation:['Umsetzung','Von der Idee bis zum aktiven Business.'],backup:['Backup','Daten exportieren, importieren oder zurücksetzen.']};
  document.getElementById('pageTitle').textContent=titles[id][0];document.getElementById('pageSubtitle').textContent=titles[id][1];document.getElementById('content').innerHTML='';
  ({dashboard,businesses,offers,packages,mindmap,synergies,candidates,inspiration,brainstorm,implementation,backup}[id])();
}
function section(html){document.getElementById('content').innerHTML=`<div class="section">${html}</div>`}
function businessName(id){return state.businesses.find(b=>b.id===id)?.name||id}
function dashboard(){
  const topConnections=[...state.businesses].map(b=>({b,n:state.connections.filter(c=>c.from===b.id||c.to===b.id).length})).sort((a,b)=>b.n-a.n).slice(0,5);
  section(`<div class="grid stats-grid"><div class="metric"><small>Businesses</small><strong>${state.businesses.length}</strong></div><div class="metric"><small>Angebote & Produkte</small><strong>${state.offers.length}</strong></div><div class="metric"><small>Pakete</small><strong>${state.packages.length}</strong></div><div class="metric"><small>Kandidaten</small><strong>${state.candidates.length}</strong></div><div class="metric"><small>Verbindungen</small><strong>${state.connections.length}</strong></div><div class="metric"><small>Cluster</small><strong>${Object.keys(CLUSTERS).length}</strong></div></div><div class="grid dashboard-split"><div class="panel"><div class="row space"><h3>Ökosystem Vorschau</h3><button class="secondary" onclick="renderPage('mindmap')">Mindmap öffnen</button></div><div class="image-placeholder" style="aspect-ratio:2/1">Interaktive Master-Mindmap mit ${state.businesses.length} Businesses</div></div><div class="panel"><h3>Stärkste Knoten</h3><div class="list">${topConnections.map(x=>`<div class="list-item"><span>${esc(x.b.name)}</span><span class="pill">${x.n} Verbindungen</span></div>`).join('')}</div></div></div>`)
}
function businesses(){
  section(`<div class="toolbar"><input id="bizSearch" placeholder="Business suchen…"><select id="clusterFilter"><option value="">Alle Cluster</option>${Object.keys(CLUSTERS).map(c=>`<option>${c}</option>`).join('')}</select></div><div id="bizGrid" class="grid business-grid"></div>`);
  const paint=()=>{const q=document.getElementById('bizSearch').value.toLowerCase(),f=document.getElementById('clusterFilter').value;document.getElementById('bizGrid').innerHTML=state.businesses.filter(b=>(!q||b.name.toLowerCase().includes(q)||(b.description||'').toLowerCase().includes(q))&&(!f||(b.clusters||[]).includes(f))).map(b=>`<div class="card business-card" onclick="openBusiness('${b.id}')"><div class="row space"><strong>${esc(b.name)}</strong><span class="status">${esc(b.status||'Idee')}</span></div><div class="tags">${(b.clusters||[]).map(c=>`<span class="tag">${esc(c)}</span>`).join('')}</div><p class="muted">${esc(b.description||'')}</p><small>${state.connections.filter(c=>c.from===b.id||c.to===b.id).length} Verbindungen · ${state.offers.filter(o=>(o.parentBusinessIds||[]).includes(b.id)).length} Angebote/Produkte</small></div>`).join('')};paint();bizSearch.oninput=paint;clusterFilter.onchange=paint
}
function openBusiness(id){
  const b=state.businesses.find(x=>x.id===id);if(!b)return;const con=state.connections.filter(c=>c.from===id||c.to===id);const offs=state.offers.filter(o=>(o.parentBusinessIds||[]).includes(id));const pkgs=state.packages.filter(p=>(p.businessIds||[]).includes(id));
  section(`<button class="secondary" onclick="renderPage('businesses')">← Zurück</button><div class="detail" style="margin-top:14px"><div class="panel"><div class="row space"><div><h2>${esc(b.name)}</h2><div class="tags">${(b.clusters||[]).map(c=>`<span class="tag">${esc(c)}</span>`).join('')}</div></div><button class="secondary" onclick="editBusiness('${id}')">Bearbeiten</button></div><p>${esc(b.description||'')}</p><div class="kv"><strong>Status</strong><span>${esc(b.status||'Idee')}</span><strong>Bestätigt</strong><span>Ja</span><strong>Notizen</strong><span>${esc(b.notes||'—')}</span></div></div><div class="panel"><h3>Direkte Verbindungen</h3><div class="connections">${con.length?con.map(c=>{const other=state.businesses.find(x=>x.id===(c.from===id?c.to:c.from));return `<div class="connection"><strong>${esc(other?.name||'Unbekannt')}</strong><br><span class="pill">${esc(c.type)}</span><p class="muted">${esc(c.description||'')}</p></div>`}).join(''):'<div class="empty">Noch keine Verbindung</div>'}</div></div></div><div class="grid detail-lower"><div class="panel"><h3>Angebote & Produkte</h3>${offs.length?offs.map(o=>`<div class="list-item"><div><strong>${esc(o.name)}</strong><div><span class="pill">${esc(o.type||'Angebot')}</span></div><small class="muted">${esc(o.description||'')}</small></div></div>`).join(''):'<div class="empty">Noch keine zugeordnet.</div>'}</div><div class="panel"><h3>Pakete</h3>${pkgs.length?pkgs.map(p=>`<div class="list-item"><div><strong>${esc(p.name)}</strong><small class="muted">${esc(p.description||'')}</small></div></div>`).join(''):'<div class="empty">Noch keine Pakete.</div>'}</div></div>`);
  pageTitle.textContent=b.name;pageSubtitle.textContent='Business-Steckbrief, Angebote und Netzwerk.'
}
function offers(){
  section(`<div class="toolbar"><input id="offerSearch" placeholder="Angebot oder Produkt suchen…"><select id="offerType"><option value="">Alle Typen</option>${[...new Set(state.offers.map(o=>o.type).filter(Boolean))].map(t=>`<option>${esc(t)}</option>`).join('')}</select><button class="secondary" onclick="addOffer()">+ Angebot / Produkt</button></div><div id="offerGrid" class="grid business-grid"></div>`);
  const paint=()=>{const q=offerSearch.value.toLowerCase(),t=offerType.value;offerGrid.innerHTML=state.offers.filter(o=>(!q||[o.name,o.description,(o.parentBusinessIds||[]).map(businessName).join(' ')].join(' ').toLowerCase().includes(q))&&(!t||o.type===t)).map(o=>`<div class="card candidate"><div class="row space"><strong>${esc(o.name)}</strong><span class="pill">${esc(o.type||'Angebot')}</span></div><p>${esc(o.description||'')}</p><p><strong>Zugeordnet zu:</strong> ${(o.parentBusinessIds||[]).map(id=>`<span class="tag">${esc(businessName(id))}</span>`).join(' ')||'—'}</p></div>`).join('')||'<div class="empty">Keine Angebote oder Produkte gefunden.</div>'};offerSearch.oninput=paint;offerType.onchange=paint;paint()
}
function packages(){
  section(`<div class="toolbar"><input id="packageSearch" placeholder="Paket suchen…"><button class="secondary" onclick="addPackage()">+ Paket</button></div><div id="packageGrid" class="grid business-grid"></div>`);
  const paint=()=>{const q=packageSearch.value.toLowerCase();packageGrid.innerHTML=state.packages.filter(p=>!q||[p.name,p.description,p.target,(p.businessIds||[]).map(businessName).join(' ')].join(' ').toLowerCase().includes(q)).map(p=>`<div class="card candidate"><div class="row space"><strong>${esc(p.name)}</strong><span class="pill">${esc(p.status||'Bestätigt')}</span></div><p>${esc(p.description||'')}</p>${p.target?`<p><strong>Zielgruppe:</strong> ${esc(p.target)}</p>`:''}<p><strong>Enthält:</strong> ${(p.businessIds||[]).map(id=>`<span class="tag">${esc(businessName(id))}</span>`).join(' ')||'—'}</p></div>`).join('')||'<div class="empty">Noch keine Pakete.</div>'};packageSearch.oninput=paint;paint()
}
function mindmap(){section(`<div class="toolbar"><select id="edgeFilter"><option value="">Alle Verbindungstypen</option>${[...new Set(state.connections.map(c=>c.type))].map(t=>`<option>${esc(t)}</option>`).join('')}</select></div><div class="mindmap-wrap"><div id="mindCanvas" class="mindmap-canvas"></div></div>`);drawMindmap();edgeFilter.onchange=drawMindmap}
function drawMindmap(){const canvas=document.getElementById('mindCanvas');if(!canvas)return;canvas.innerHTML='';const center={x:640,y:390};const svg=document.createElementNS('http://www.w3.org/2000/svg','svg');svg.setAttribute('class','edge-layer');svg.setAttribute('width','1500');svg.setAttribute('height','950');canvas.appendChild(svg);const clusterNames=Object.keys(CLUSTERS);const positions={};clusterNames.forEach((cl,ci)=>{const items=state.businesses.filter(b=>(b.clusters||[]).includes(cl));const angleBase=(Math.PI*2/clusterNames.length)*ci-Math.PI/2;const hubX=center.x+Math.cos(angleBase)*320,hubY=center.y+Math.sin(angleBase)*260;const label=document.createElement('div');label.className='cluster-label';label.style.left=(hubX-50)+'px';label.style.top=(hubY-65)+'px';label.textContent=cl;canvas.appendChild(label);items.forEach((b,i)=>{const spread=(i-(items.length-1)/2)*0.22;const angle=angleBase+spread;const radius=430+Math.min(100,Math.abs(i-(items.length-1)/2)*18);const x=center.x+Math.cos(angle)*radius,y=center.y+Math.sin(angle)*radius;positions[b.id]={x,y};const n=document.createElement('div');n.className='node';n.style.left=x+'px';n.style.top=y+'px';n.style.background=CLUSTERS[b.clusters?.[0]]||'#fff';n.innerHTML=`<strong>${esc(b.name)}</strong><div class="muted" style="font-size:11px;margin-top:4px">${esc(b.clusters?.[0]||'')}</div>`;n.onclick=()=>openBusiness(b.id);canvas.appendChild(n)})});const c=document.createElement('div');c.className='node center';c.style.left=center.x+'px';c.style.top=center.y+'px';c.innerHTML='MASTER<br>MINDMAP<div class="muted" style="font-size:11px;margin-top:6px">Business Ecosystem</div>';canvas.appendChild(c);const filter=edgeFilter?.value||'';state.connections.filter(e=>!filter||e.type===filter).forEach(e=>{const a=positions[e.from],b=positions[e.to];if(!a||!b)return;const line=document.createElementNS('http://www.w3.org/2000/svg','path');const ax=a.x+90,ay=a.y+35,bx=b.x+90,by=b.y+35;const mx=(ax+bx)/2,my=(ay+by)/2-30;line.setAttribute('d',`M ${ax} ${ay} Q ${mx} ${my} ${bx} ${by}`);line.setAttribute('class','edge');svg.appendChild(line)})}
function synergies(){const types=[...new Set(state.connections.map(c=>c.type))];section(`<div class="grid synergy-grid"><div class="panel"><h3>Verbindungstypen</h3>${types.map(t=>`<div class="list-item"><span>${esc(t)}</span><span class="pill">${state.connections.filter(c=>c.type===t).length}</span></div>`).join('')}</div><div class="panel"><h3>Alle bestätigten Synergien</h3><div class="list">${state.connections.map(c=>`<div class="list-item"><div><strong>${esc(businessName(c.from))} → ${esc(businessName(c.to))}</strong><div><span class="pill">${esc(c.type)}</span></div><small class="muted">${esc(c.description||'')}</small></div></div>`).join('')}</div></div></div>`)}
function candidates(){section(`<div class="toolbar"><input id="candSearch" placeholder="Kandidat suchen…"><select id="candEffort"><option value="">Alle Aufwände</option><option>Einfach</option><option>Einfach–Mittel</option><option>Mittel</option><option>Mittel–Aufwendig</option><option>Aufwendig</option><option>Sehr aufwendig</option></select></div><div id="candGrid" class="grid business-grid"></div>`);const paint=()=>{const q=(candSearch.value||'').toLowerCase(),e=candEffort.value;candGrid.innerHTML=state.candidates.filter(c=>(!q||[c.name,c.description,c.target,c.resources,c.channels,(c.synergies||[]).join(' ')].join(' ').toLowerCase().includes(q))&&(!e||c.effort===e)).map(c=>`<div class="card candidate"><div class="row space"><strong>${esc(c.name)}</strong><span class="pill">${esc(c.status||'Kandidat')}</span></div><div class="tags">${(c.clusters||[]).map(x=>`<span class="tag">${esc(x)}</span>`).join('')}</div><p>${esc(c.description||'')}</p>${c.target?`<p><strong>Zielgruppe:</strong> ${esc(c.target)}</p>`:''}${c.synergies?.length?`<p><strong>Synergien:</strong> ${c.synergies.map(esc).join(' · ')}</p>`:''}${c.resources?`<p><strong>Ressourcen:</strong> ${esc(c.resources)}</p>`:''}${c.channels?`<p><strong>Verkauf:</strong> ${esc(c.channels)}</p>`:''}${c.effort?`<p><strong>Aufwand:</strong> <span class="pill">${esc(c.effort)}</span></p>`:''}<div class="row"><button class="primary" onclick="approveCandidate('${c.id}')">Als Business bestätigen</button><button class="danger" onclick="removeCandidate('${c.id}')">Verwerfen</button></div></div>`).join('')||'<div class="empty">Keine Kandidaten gefunden.</div>'};candSearch.oninput=paint;candEffort.onchange=paint;paint()}
function approveCandidate(id){const c=state.candidates.find(x=>x.id===id);if(!c)return;state.businesses.push({id:'biz'+Date.now(),name:c.name,description:c.description,clusters:c.clusters||[],status:'Idee',confirmed:true,notes:[c.target&&'Zielgruppe: '+c.target,c.synergies?.length&&'Synergien: '+c.synergies.join(' · '),c.resources&&'Ressourcen: '+c.resources,c.channels&&'Verkauf: '+c.channels,c.effort&&'Aufwand: '+c.effort].filter(Boolean).join('\n'),images:[]});state.candidates=state.candidates.filter(x=>x.id!==id);save();renderPage('candidates')}
function removeCandidate(id){state.candidates=state.candidates.filter(x=>x.id!==id);save();renderPage('candidates')}
function inspiration(){section(`<div class="panel"><div class="row space"><h3>Inspirationssammlung</h3><button class="secondary" onclick="addInspiration()">+ Inspiration</button></div>${state.inspiration.length?`<div class="grid business-grid">${state.inspiration.map(i=>`<div class="card"><div class="image-placeholder">${i.url?'Bild-Link gespeichert':'Moodboard'}</div><h4>${esc(i.title)}</h4><p class="muted">${esc(i.business||'Allgemein')}</p><span class="pill">${esc(i.status||'Nicht geprüft')}</span></div>`).join('')}</div>`:'<div class="empty">Noch keine Bilder oder Moodboard-Ideen gespeichert.</div>'}</div>`)}
function brainstorm(){section(`<div class="panel"><div class="row space"><h3>Freies Brainstorming</h3><button class="secondary" onclick="addBrainstorm()">+ Gedanke</button></div><div class="list">${state.brainstorm.length?state.brainstorm.map(x=>`<div class="list-item"><div>${esc(x.text)}</div><button class="secondary" onclick="brainToCandidate('${x.id}')">→ Kandidat</button></div>`).join(''):'<div class="empty">Noch keine losen Gedanken gespeichert.</div>'}</div></div>`)}
function implementation(){const stages=['Idee','Recherche','Konzept','Businessplan','Test','Aufbau','Aktiv','Skalierung'];section(`<div class="grid business-grid">${stages.map(s=>`<div class="panel"><h3>${s}</h3>${state.businesses.filter(b=>b.status===s).map(b=>`<div class="list-item"><span>${esc(b.name)}</span><button class="secondary" onclick="advance('${b.id}')">Weiter</button></div>`).join('')||'<div class="muted">—</div>'}</div>`).join('')}</div>`)}
function advance(id){const stages=['Idee','Recherche','Konzept','Businessplan','Test','Aufbau','Aktiv','Skalierung'];const b=state.businesses.find(x=>x.id===id);const i=stages.indexOf(b.status);if(i<stages.length-1)b.status=stages[i+1];save();renderPage('implementation')}
function backup(){section(`<div class="grid backup-grid"><div class="panel"><h3>Export</h3><p>Speichert Businesses, Angebote & Produkte, Pakete, Verbindungen, Kandidaten, Inspirationen und Brainstorming-Daten.</p><p class="muted">Dateiname enthält automatisch Datum und ${APP_VERSION}.</p><button class="primary" onclick="exportData()">JSON exportieren</button></div><div class="panel"><h3>Import</h3><input type="file" id="importFile" accept="application/json"><button class="secondary" style="margin-top:10px" onclick="importData()">Importieren</button></div><div class="panel"><h3>Reset</h3><p>Setzt die PWA auf die mitgelieferten Startdaten dieser Version zurück.</p><button class="danger" onclick="resetData()">Startdaten wiederherstellen</button></div></div>`)}
function exportData(){const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);const d=new Date();const yyyy=d.getFullYear();const mm=String(d.getMonth()+1).padStart(2,'0');const dd=String(d.getDate()).padStart(2,'0');const version=APP_VERSION.replace(/\s+/g,'-').toLowerCase();a.download=`business-ecosystem-backup-${yyyy}-${mm}-${dd}-${version}.json`;a.click();URL.revokeObjectURL(a.href)}
function importData(){const f=importFile.files[0];if(!f)return;const r=new FileReader();r.onload=()=>{try{state=JSON.parse(r.result);migrateState();renderPage('dashboard')}catch(e){console.error(e);alert('Ungültige JSON-Datei')}};r.readAsText(f)}
function resetData(){if(confirm('Wirklich auf Startdaten zurücksetzen?')){state=clone(defaultState);save();renderPage('dashboard')}}
function modal(html){modalRoot.innerHTML=`<div class="modal-backdrop" onclick="if(event.target===this)closeModal()"><div class="modal">${html}</div></div>`}
function closeModal(){modalRoot.innerHTML=''}
function addBusiness(){modal(`<h2>Neues bestätigtes Business</h2><div class="form-grid"><label>Name<input id="mName"></label><label>Status<select id="mStatus"><option>Idee</option><option>Recherche</option><option>Konzept</option></select></label><label class="wide">Beschreibung<textarea id="mDesc"></textarea></label><label class="wide">Cluster (mit Komma trennen)<input id="mClusters" placeholder="Food & Desserts, Events & Weddings"></label></div><div class="modal-actions"><button class="secondary" onclick="closeModal()">Abbrechen</button><button class="primary" onclick="saveBusiness()">Speichern</button></div>`)}
function saveBusiness(){const name=mName.value.trim();if(!name)return;state.businesses.push({id:'biz'+Date.now(),name,description:mDesc.value.trim(),clusters:mClusters.value.split(',').map(x=>x.trim()).filter(Boolean),status:mStatus.value,confirmed:true,notes:'',images:[]});save();closeModal();renderPage('businesses')}
function editBusiness(id){const b=state.businesses.find(x=>x.id===id);modal(`<h2>${esc(b.name)} bearbeiten</h2><div class="form-grid"><label>Name<input id="eName" value="${esc(b.name)}"></label><label>Status<select id="eStatus">${['Idee','Recherche','Konzept','Businessplan','Test','Aufbau','Aktiv','Skalierung'].map(s=>`<option ${s===b.status?'selected':''}>${s}</option>`).join('')}</select></label><label class="wide">Beschreibung<textarea id="eDesc">${esc(b.description||'')}</textarea></label><label class="wide">Cluster<input id="eClusters" value="${esc((b.clusters||[]).join(', '))}"></label><label class="wide">Notizen<textarea id="eNotes">${esc(b.notes||'')}</textarea></label></div><div class="modal-actions"><button class="secondary" onclick="closeModal()">Abbrechen</button><button class="primary" onclick="saveEdit('${id}')">Speichern</button></div>`)}
function saveEdit(id){const b=state.businesses.find(x=>x.id===id);b.name=eName.value;b.status=eStatus.value;b.description=eDesc.value;b.clusters=eClusters.value.split(',').map(x=>x.trim()).filter(Boolean);b.notes=eNotes.value;save();closeModal();openBusiness(id)}
function addCandidate(){modal(`<h2>Neuer Kandidat</h2><div class="form-grid"><label class="wide">Name<input id="cName"></label><label class="wide">Beschreibung<textarea id="cDesc"></textarea></label><label class="wide">Cluster<input id="cClusters"></label></div><div class="modal-actions"><button class="secondary" onclick="closeModal()">Abbrechen</button><button class="primary" onclick="saveCandidate()">Speichern</button></div>`)}
function saveCandidate(){if(!cName.value.trim())return;state.candidates.push({id:'cand'+Date.now(),name:cName.value.trim(),description:cDesc.value.trim(),clusters:cClusters.value.split(',').map(x=>x.trim()).filter(Boolean),status:'Kandidat'});save();closeModal();renderPage('candidates')}
function addOffer(){modal(`<h2>Neues Angebot / Produkt</h2><div class="form-grid"><label>Name<input id="oName"></label><label>Typ<input id="oType" placeholder="Produkt, Add-on, Angebot …"></label><label class="wide">Beschreibung<textarea id="oDesc"></textarea></label><label class="wide">Business-IDs oder Namen (mit Komma trennen)<input id="oParents" placeholder="Airbnb, Gnadenhof"></label></div><div class="modal-actions"><button class="secondary" onclick="closeModal()">Abbrechen</button><button class="primary" onclick="saveOffer()">Speichern</button></div>`)}
function resolveBusinessIds(text){return text.split(',').map(x=>x.trim()).filter(Boolean).map(v=>state.businesses.find(b=>b.id===v||b.name.toLowerCase()===v.toLowerCase())?.id).filter(Boolean)}
function saveOffer(){if(!oName.value.trim())return;state.offers.push({id:'offer'+Date.now(),name:oName.value.trim(),type:oType.value.trim()||'Angebot',description:oDesc.value.trim(),parentBusinessIds:resolveBusinessIds(oParents.value),status:'Bestätigt'});save();closeModal();renderPage('offers')}
function addPackage(){modal(`<h2>Neues Paket</h2><div class="form-grid"><label class="wide">Name<input id="pName"></label><label class="wide">Beschreibung<textarea id="pDesc"></textarea></label><label class="wide">Zielgruppe<input id="pTarget"></label><label class="wide">Businesses (Namen oder IDs, mit Komma trennen)<input id="pBusinesses"></label></div><div class="modal-actions"><button class="secondary" onclick="closeModal()">Abbrechen</button><button class="primary" onclick="savePackage()">Speichern</button></div>`)}
function savePackage(){if(!pName.value.trim())return;state.packages.push({id:'pkg'+Date.now(),name:pName.value.trim(),description:pDesc.value.trim(),target:pTarget.value.trim(),businessIds:resolveBusinessIds(pBusinesses.value),status:'Bestätigt'});save();closeModal();renderPage('packages')}
function addBrainstorm(){modal(`<h2>Brainstorming-Idee</h2><label>Gedanke<textarea id="bText"></textarea></label><div class="modal-actions"><button class="secondary" onclick="closeModal()">Abbrechen</button><button class="primary" onclick="saveBrainstorm()">Speichern</button></div>`)}
function saveBrainstorm(){if(!bText.value.trim())return;state.brainstorm.push({id:'brain'+Date.now(),text:bText.value.trim()});save();closeModal();renderPage('brainstorm')}
function brainToCandidate(id){const b=state.brainstorm.find(x=>x.id===id);state.candidates.push({id:'cand'+Date.now(),name:b.text.slice(0,60),description:b.text,clusters:[],status:'Kandidat'});state.brainstorm=state.brainstorm.filter(x=>x.id!==id);save();renderPage('brainstorm')}
function addInspiration(){modal(`<h2>Inspiration speichern</h2><div class="form-grid"><label>Titel<input id="iTitle"></label><label>Business<input id="iBusiness"></label><label class="wide">Bild-URL / Hinweis<input id="iUrl"></label><label>Status<select id="iStatus"><option>Nicht geprüft</option><option>Bestätigt</option><option>Abgelehnt</option></select></label></div><div class="modal-actions"><button class="secondary" onclick="closeModal()">Abbrechen</button><button class="primary" onclick="saveInspiration()">Speichern</button></div>`)}
function saveInspiration(){if(!iTitle.value.trim())return;state.inspiration.push({id:'img'+Date.now(),title:iTitle.value.trim(),business:iBusiness.value.trim(),url:iUrl.value.trim(),status:iStatus.value});save();closeModal();renderPage('inspiration')}
function esc(s){return String(s??'').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;')}
addBusinessBtn.onclick=addBusiness;addCandidateBtn.onclick=addCandidate;exportQuick.onclick=exportData;
if('serviceWorker' in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});
renderPage('dashboard');
